import pandas as pd

def get_summary(quarter_dir, accession):
    df=pd.read_csv(f'{quarter_dir}/SUMMARYPAGE.tsv', sep='\t', dtype={'ACCESSION_NUMBER':str})
    row=df[df.ACCESSION_NUMBER==accession]
    if row.empty:
        raise ValueError(f'No summary row for {accession}')
    r=row.iloc[0]
    return int(r.TABLEVALUETOTAL), int(r.TABLEENTRYTOTAL)

renaissance_acc='0001037389-25-000064'
q3_aum, q3_entries = get_summary('/root/2025-q3', renaissance_acc)
print('Renaissance Q3 aum', q3_aum, 'entries', q3_entries)
