def get_summary(quarter_dir, accession):
    df=pd.read_csv(f'{quarter_dir}/SUMMARYPAGE.tsv', sep='\t', dtype={'ACCESSION_NUMBER':str})
    row=df[df.ACCESSION_NUMBER==accession]
    if row.empty:
        raise ValueError(f'No summary row for {accession}')
    r=row.iloc[0]
